SELECT PAS.base_date, PAS.agg_status, MC.code_name AS agg_status_name, PAS.agg_start_at, PAS.agg_end_at, PAS.retry_count, PAS.error_message, PAS.created_at, PAS.updated_at FROM PAYMENT_AGG_STATUS PAS LEFT JOIN MST_CODE MC ON MC.code_group = 'PAYMENT_AGG_STATUS' AND MC.code = PAS.agg_status AND MC.use_yn = 'Y' WHERE 1=1
AND PAS.base_date >= #{dto.baseDateFrom}
AND PAS.base_date <= #{dto.baseDateTo}
ORDER BY PAS.base_date DESC OFFSET #{dto.offset} ROWS FETCH NEXT #{dto.size} ROWS ONLY

SELECT COUNT(*)
FROM PAYMENT_AGG_STATUS PAS
WHERE 1=1


    AND PAS.base_date >= #{dto.baseDateFrom}



    AND PAS.base_date <= #{dto.baseDateTo}
